--
-- Base de datos: `u654724793_emporium`
--

DELIMITER $$
--
-- Procedimientos
--
CREATE DEFINER=`u654724793_ajeg25devemp`@`127.0.0.1` PROCEDURE `cursor_vacaciones_fecha_especifica` (IN `dateToCheck` DATE)  MODIFIES SQL DATA BEGIN
    DECLARE done INT DEFAULT FALSE;
    DECLARE idEmp VARCHAR(255) DEFAULT "";
    DECLARE idChec VARCHAR(255) DEFAULT "";
    DECLARE utilizables VARCHAR(255) DEFAULT "";
    DECLARE Inicio VARCHAR(255) DEFAULT "";
    DECLARE AniosAntiguedad INT DEFAULT 0; 
    
    DECLARE cursorEmpleados CURSOR FOR 
        SELECT year(dateToCheck) - year(ingreso) as AniosAntiguedad, idEmpleado, idChecador, ingreso, utilizables 
        FROM u654724793_emporium.tc_empleados 
        WHERE isActive = 1;
        
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

    OPEN cursorEmpleados;

    read_loop: LOOP
        FETCH cursorEmpleados INTO AniosAntiguedad, idEmp, idChec, Inicio, utilizables;
        
        IF done THEN
            LEAVE read_loop;
        END IF;

        -- Verificamos si es el aniversario (día y mes)
        IF DATE_FORMAT(Inicio, '%m-%d') = DATE_FORMAT(dateToCheck, '%m-%d') THEN
            
            -- Asignación de días según antigüedad
            IF (AniosAntiguedad = 1) THEN SET @dias = 12;
            ELSEIF (AniosAntiguedad = 2) THEN SET @dias = 14;
            ELSEIF (AniosAntiguedad = 3) THEN SET @dias = 16;
            ELSEIF (AniosAntiguedad = 4) THEN SET @dias = 18;
            ELSEIF (AniosAntiguedad = 5) THEN SET @dias = 20;
            ELSEIF (AniosAntiguedad >= 6 AND AniosAntiguedad <= 10) THEN SET @dias = 22;
            ELSEIF (AniosAntiguedad >= 11 AND AniosAntiguedad <= 15) THEN SET @dias = 24;
            ELSEIF (AniosAntiguedad >= 16 AND AniosAntiguedad <= 20) THEN SET @dias = 26;
            ELSEIF (AniosAntiguedad >= 21 AND AniosAntiguedad <= 25) THEN SET @dias = 28;
            ELSEIF (AniosAntiguedad >= 26 AND AniosAntiguedad <= 30) THEN SET @dias = 30;
            ELSE SET @dias = 0;
            END IF;

            -- INICIO DE LA NUEVA LÓGICA DE ACTUALIZACIÓN/INSERCIÓN
            IF @dias > 0 THEN
            
                -- 1. Primer caso: Verificar si hay registro manual sin vacaciones registradas
                IF (SELECT COUNT(*) FROM tr_vacacionespendientes 
                    WHERE idEmpleado = idEmp 
                    AND year(fechaActualizacion) = year(dateToCheck) 
                    AND registroManual = 1 
                    AND registroVacaciones = 0) > 0 THEN
                    
                    -- Si existe, actualizamos sumando días y marcando registroVacaciones
                    UPDATE tr_vacacionespendientes 
                    SET diasPendientes = diasPendientes + @dias, 
                        registroVacaciones = 1 
                    WHERE idEmpleado = idEmp 
                    AND year(fechaActualizacion) = year(dateToCheck)
                    AND registroManual = 1; -- (Aseguramos actualizar solo el manual)

                ELSE
                    -- 2. Segundo caso: Si NO se cumplió lo anterior, verificamos si no existe registro
                    IF (SELECT COUNT(*) FROM tr_vacacionespendientes 
                        WHERE idEmpleado = idEmp 
                        AND year(fechaActualizacion) = year(dateToCheck)) = 0 THEN
                        
                        -- Insertamos nuevo registro
                        INSERT INTO tr_vacacionespendientes 
                        VALUES (null, idEmp, @dias, dateToCheck, idChec, 1, 0, 1);
                        
                        -- Desactivamos las del año anterior
                        UPDATE tr_vacacionespendientes 
                        SET utilizables = 0 
                        WHERE idEmpleado = idEmp 
                        AND year(fechaActualizacion) = (year(dateToCheck)-1);
                        
                    END IF;
                    
                END IF; 
                
            END IF; 

        END IF; 
    END LOOP;

    CLOSE cursorEmpleados;
END$$

DELIMITER ;

